	('gauda', 'gauda', 'Gauda', 'capital', 'West Bengal', '0101000020E6100000D578E926310856406EA301BC05E23840', true, 'place-gauda', 1526, '{"c": "Amitabha Gupta, CC BY 4.0", "d": "mosque in West Bengal", "i": "https://thumb.wikimedia.org/wikipedia/commons/thumb/5/50/Baraduari_Mosque_alias_Barasona_Mosque_at_Gaur_05.jpg/500px-Baraduari_Mosque_alias_Barasona_Mosque_at_Gaur_05.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "n": "Baro Shona Masjid", "p": "https://commons.wikimedia.org/wiki/File:Baraduari_Mosque_alias_Barasona_Mosque_at_Gaur_05.jpg", "q": "Q13058783", "t": "mosque", "w": "Baro_Shona_Masjid", "y": 1526}'),
	('madurai', 'madurai', 'Madurai', 'capital', 'Tamil Nadu', '0101000020E61000001DC9E53FA48753402D431CEBE2D62340', false, 'pandya-meenakshi', 1200, '{"c": "Vyacheslav Argenberg, CC BY 4.0", "d": "historic Hindu temple in Madurai, Tamil Nadu, India", "i": "https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a7/Meenakshi_Temple%2C_Gopuram%2C_Madurai%2C_India.jpg/500px-Meenakshi_Temple%2C_Gopuram%2C_Madurai%2C_India.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail", "n": "Meenakshi Temple", "p": "https://commons.wikimedia.org/wiki/File:Meenakshi_Temple,_Gopuram,_Madurai,_India.jpg", "q": "Q1424358", "t": "temple", "w": "Meenakshi_Temple", "y": 1200}'),
