INSERT INTO public.historical_items VALUES
	('sii-ii-85', 'sii-ii-85', 'Rajaraja I''s inventory of temple images at Thanjavur', 'inscription', 'Stone (pillar of the west enclosure)', 'Tamil', 'Tamil', 'thanjavur', 'SII vol. II, no. 85', 'evidence-stone-inscription', true, false, 1014, 'about', 'likely', 'By the 29th year of his reign, Rajaraja I had installed a large set of copper images in the Thanjavur temple — several of Ganapati among them — and had them measured and recorded on its walls.', 'The inscription says the images were measured against the cubit rule kept in the temple, then cut in stone. That makes it an official inventory of the temple''s treasure. The length units (viral and others) are the editors'' transliterations of Tamil measures.', 'medium', 'high', 'high', false),
	('sii-ii-88', 'sii-ii-88', 'A bell-metal dish for the Ganapati shrine, given by a tax official', 'inscription', 'Stone (pillar of the west enclosure)', 'Tamil', 'Tamil', 'thanjavur', 'SII vol. II, no. 88', 'evidence-stone-inscription', true, false, 1014, 'about', 'likely', 'By the 29th year of Rajaraja I''s reign, a servant of the king named Kanjan Kondaiyan, from Kamadamangalam, had given a bell-metal dish weighing 29 palam to the Ganapati shrine in the Thanjavur temple, and the gift was recorded on a pillar.', 'Gifts to the temple were cut in stone beside the shrine they went to, with the donor''s name, home village and post. This donor is called a servant of the king and master of the rent roll in the department of taxes on endowments. The editors say he was "apparently" employed in the department that regulated those taxes, so the job is their reading of the text. The palam is a unit of weight.', 'medium', 'high', 'medium', false);
